insert into public.regions ("id","name","rarity","sort_order","image_path","requires_map_fragment","description") values
('plunder','약탈자의 항로','rare',14,'plunder/scenery-v1.png',true,'검은 돛과 붉은 깃발이 스치는 해적들의 항로. 난파선과 황동 등불 사이에 숨은 보물과 바다 친구들을 찾아보세요.')
insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction") values
('plunder-anchor-whisker-sealion','fish','닻수염 해적바다사자','닻처럼 휜 수염과 붉은 망토 같은 지느러미를 가진 바다사자예요.','0.22','0.78','0.021',108,'epic','fish/epic/plunder-anchor-whisker-sealion_v1_thumbnail.png',775,'fish/epic/plunder-anchor-whisker-sealion_v1_sprite.png','plunder','swim',true,'both'),
('plunder-bandana-octopus','fish','두건문어','붉은 두건 같은 머리 주름과 짧게 말린 여덟 다리를 가진 문어예요.','0.85','0.95','0.012',51,'common','fish/normal/plunder-bandana-octopus_v1_thumbnail.png',59,'fish/normal/plunder-bandana-octopus_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-barca','fish','돌아오지 않는 선장, 바르카','등의 빈 선장실에 등불을 밝힌 채 닻과 조타륜 같은 집게로 돌아올 주인을 기다려요.','0.85','0.94','0.012',125,'mythic','fish/mythic/plunder-barca_v1_thumbnail.png',2800,'fish/mythic/plunder-barca_swim8_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-barnacle-sailor-chair','decoration','따개비 선원 의자','낡은 선원 의자에 작은 따개비들이 자리를 잡았어요.',null,null,'0',48,'common','decorations/normal/plunder-barnacle-sailor-chair_v1_thumbnail.png',30,null,'plunder','fixed',false,'both'),
('plunder-bloodsail','fish','침몰한 맹세, 블러드세일','붉은 돛 같은 지느러미와 유리 몸속의 낡은 검으로 침몰한 약속을 지키는 오징어예요.','0.2','0.76','0.016',135,'mythic','fish/mythic/plunder-bloodsail_v1_thumbnail.png',2750,'fish/mythic/plunder-bloodsail_swim8_v1_sprite.png','plunder','swim',true,'both'),
('plunder-blue-flame-stern-lantern','decoration','푸른 불꽃 선미등','푸른 불빛이 유리 안에서 조용히 흔들리는 선미등이에요.',null,null,'0',65,'rare','decorations/rare/plunder-blue-flame-stern-lantern_v1_thumbnail.png',148,null,'plunder','fixed',false,'both'),
('plunder-bounty-gold-puffer','fish','현상금 금화복어','몸을 부풀리면 동전 같은 둥근 비늘 무늬가 드러나는 복어예요.','0.3','0.78','0.028',65,'rare','fish/rare/plunder-bounty-gold-puffer_v1_thumbnail.png',255,'fish/rare/plunder-bounty-gold-puffer_v1_sprite.png','plunder','swim',true,'both'),
('plunder-cannon-ink-squid','fish','포탄먹물 오징어','포탄처럼 둥근 머리와 짧은 도화선 모양 볏을 지닌 오징어예요.','0.24','0.74','0.028',65,'rare','fish/rare/plunder-cannon-ink-squid_v1_thumbnail.png',225,'fish/rare/plunder-cannon-ink-squid_v1_sprite.png','plunder','swim',true,'both'),
('plunder-captains-red-armchair','decoration','선장의 붉은 안락의자','붉은 쿠션과 황동 팔걸이가 달린 의자예요. 선장의 빈자리를 지키고 있어요.',null,null,'0',70,'rare','decorations/rare/plunder-captains-red-armchair_v1_thumbnail.png',160,null,'plunder','fixed',false,'both'),
('plunder-captains-single-boot','trash','한 짝뿐인 선장 장화','짝을 잃은 선장 장화예요. 모래가 가득 들어 이제는 발보다 무거워요.','0.89','0.96','0.001',38,'common','trash/normal/plunder-captains-single-boot_v1_thumbnail.png',8,null,'plunder','fixed',false,'both'),
('plunder-deck-cleaner-shrimp','fish','갑판청소 새우','솔 같은 수염으로 바닥을 쓸며 선창 주변을 돌아다녀요.','0.85','0.95','0.012',44,'common','fish/normal/plunder-deck-cleaner-shrimp_v1_thumbnail.png',50,'fish/normal/plunder-deck-cleaner-shrimp_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-dud-salute-shell','trash','불발된 축포탄','터지지 않은 작은 축포탄이에요. 안쪽에는 축하 색종이가 남아 있어요.','0.89','0.96','0.001',38,'common','trash/normal/plunder-dud-salute-shell_v1_thumbnail.png',10,null,'plunder','fixed',false,'both'),
('plunder-empty-supply-barrel','decoration','빈 보급품 나무통','뚜껑이 살짝 열린 보급품 통이에요. 안쪽은 깨끗하게 비어 있어요.',null,null,'0',48,'common','decorations/normal/plunder-empty-supply-barrel_v1_thumbnail.png',32,null,'plunder','fixed',false,'both'),
('plunder-erased-sailor-tag','trash','이름 지워진 선원 명찰','소금기에 이름이 지워진 명찰이에요. 작은 구멍에 낡은 끈이 남아 있어요.','0.89','0.96','0.001',38,'common','trash/normal/plunder-erased-sailor-tag_v1_thumbnail.png',7,null,'plunder','fixed',false,'both'),
('plunder-folded-pirate-flag','decoration','접어 둔 해적깃발','접어 둔 검은 깃발이에요. 상자 옆으로 천 끝이 살짝 흘러내려요.',null,null,'0',50,'common','decorations/normal/plunder-folded-pirate-flag_v1_thumbnail.png',34,null,'plunder','fixed',false,'both'),
('plunder-half-eaten-hard-tack','trash','반쯤 먹힌 건빵','누군가 한입 베어 문 건빵이에요. 바닷물에 젖어 조금 말랑해졌어요.','0.89','0.96','0.001',38,'common','trash/normal/plunder-half-eaten-hard-tack_v1_thumbnail.png',6,null,'plunder','fixed',false,'both'),
('plunder-hollow-gold-crown','trash','속 빈 황금 왕관','황금 왕관처럼 보이지만 안쪽은 얇은 종이예요.','0.89','0.96','0.001',48,'rare','trash/rare/plunder-hollow-gold-crown_v1_thumbnail.png',38,null,'plunder','fixed',false,'both'),
('plunder-jewel-appraiser-shrimp','fish','보석감정 돋보기새우','돋보기 같은 집게 너머로 작은 보석을 들여다보는 새우예요.','0.85','0.95','0.012',47,'common','fish/normal/plunder-jewel-appraiser-shrimp_v1_thumbnail.png',56,'fish/normal/plunder-jewel-appraiser-shrimp_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-lookout-goby','fish','망보기 망둑어','망원경처럼 솟은 두 눈으로 멀리서 오는 배를 살펴봐요.','0.55','0.83','0.028',44,'common','fish/normal/plunder-lookout-goby_v1_thumbnail.png',52,'fish/normal/plunder-lookout-goby_v1_sprite.png','plunder','swim',true,'both'),
('plunder-loot-king-hermit','fish','장물왕 소라게','진주와 은식기가 담긴 보물상자를 집으로 삼은 커다란 소라게예요.','0.85','0.95','0.012',100,'epic','fish/epic/plunder-loot-king-hermit_v1_thumbnail.png',750,'fish/epic/plunder-loot-king-hermit_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-morgar','fish','마지막 해적왕, 모르가르','산호 왕관과 붉은 망토 지느러미를 두른 곰치왕이에요. 목 아래의 황금 열쇠를 지켜요.','0.22','0.78','0.016',145,'mythic','fish/mythic/plunder-morgar_v1_thumbnail.png',2850,'fish/mythic/plunder-morgar_swim8_v1_sprite.png','plunder','swim',true,'both'),
('plunder-one-eyed-carp','fish','외눈붕어','큰 눈 하나와 오래된 흉터 무늬를 지닌 느긋한 붕어예요.','0.24','0.78','0.028',48,'common','fish/normal/plunder-one-eyed-carp_v1_thumbnail.png',57,'fish/normal/plunder-one-eyed-carp_v1_sprite.png','plunder','swim',true,'both'),
('plunder-peg-leg-crab','fish','외다리 의족게','한쪽 다리가 나무 의족처럼 곧게 뻗은 씩씩한 게예요.','0.85','0.95','0.012',49,'common','fish/normal/plunder-peg-leg-crab_v1_thumbnail.png',55,'fish/normal/plunder-peg-leg-crab_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-pirate-captain-horseshoe','fish','해적선장 투구게','삼각모를 닮은 넓은 등껍질과 긴 꼬리를 가진 투구게예요.','0.85','0.95','0.012',70,'rare','fish/rare/plunder-pirate-captain-horseshoe_v1_thumbnail.png',250,'fish/rare/plunder-pirate-captain-horseshoe_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-plunder-crown-urchin','fish','약탈왕관 성게','황동빛 가시 사이에 작은 보석빛 무늬를 품은 왕관 같은 성게예요.','0.86','0.95','0.012',62,'rare','fish/rare/plunder-plunder-crown-urchin_v1_thumbnail.png',260,'fish/rare/plunder-plunder-crown-urchin_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-rope-mooring-post','decoration','밧줄 감긴 계선주','굵은 밧줄이 감긴 계선주예요. 작은 항구를 꾸미기 좋아요.',null,null,'0',45,'common','decorations/normal/plunder-rope-mooring-post_v1_thumbnail.png',28,null,'plunder','fixed',false,'both'),
('plunder-rope-tail-pipefish','fish','밧줄꼬리 실고기','밧줄처럼 꼬인 가느다란 꼬리 끝에 작은 매듭이 보여요.','0.22','0.75','0.028',56,'common','fish/normal/plunder-rope-tail-pipefish_v1_thumbnail.png',49,'fish/normal/plunder-rope-tail-pipefish_v1_sprite.png','plunder','swim',true,'both'),
('plunder-rum-barrel-puffer','fish','럼통 복어','나무통 같은 몸무늬와 작은 지느러미를 가진 통통한 복어예요.','0.24','0.78','0.028',46,'common','fish/normal/plunder-rum-barrel-puffer_v1_thumbnail.png',48,'fish/normal/plunder-rum-barrel-puffer_v1_sprite.png','plunder','swim',true,'both'),
('plunder-rum-bottle-neck','trash','병목만 남은 럼주병','병은 사라졌는데 코르크는 여전히 꼭 닫혀 있어요.','0.89','0.96','0.001',38,'common','trash/normal/plunder-rum-bottle-neck_v1_thumbnail.png',9,null,'plunder','fixed',false,'both'),
('plunder-sailor-sock-moray','fish','선원양말 곰치','낡은 선원 양말 같은 줄무늬가 긴 몸을 따라 이어지는 곰치예요.','0.25','0.8','0.028',73,'rare','fish/rare/plunder-sailor-sock-moray_v1_thumbnail.png',220,'fish/rare/plunder-sailor-sock-moray_v1_sprite.png','plunder','swim',true,'both'),
('plunder-sand-cannonball-pile','decoration','모래 덮인 포탄 더미','둥근 포탄 세 개가 모래 위에 나란히 포개져 있어요.',null,null,'0',44,'common','decorations/normal/plunder-sand-cannonball-pile_v1_thumbnail.png',36,null,'plunder','fixed',false,'both'),
('plunder-secret-trading-desk','decoration','해적의 비밀 거래대','저울과 주머니, 펼친 장부가 놓인 거래대예요. 조용한 흥정이 시작될 것 같아요.',null,null,'0',75,'rare','decorations/rare/plunder-secret-trading-desk_v1_thumbnail.png',172,null,'plunder','fixed',false,'both'),
('plunder-skull-weapon-rack','decoration','해골 문장 무기걸이','낡은 검 두 자루와 해골 문장이 걸린 받침이에요. 오래된 항해 이야기가 묻어 있어요.',null,null,'0',75,'rare','decorations/rare/plunder-skull-weapon-rack_v1_thumbnail.png',196,null,'plunder','fixed',false,'both'),
('plunder-smuggler-pouch-puffer','fish','밀수꾼 주머니복','볼주머니에 작은 조개를 몰래 숨겨 둔 장난꾸러기 복어예요.','0.32','0.78','0.028',47,'common','fish/normal/plunder-smuggler-pouch-puffer_v1_thumbnail.png',53,'fish/normal/plunder-smuggler-pouch-puffer_v1_sprite.png','plunder','swim',true,'both'),
('plunder-smuggler-vault-turtle','fish','밀수금고 거북','황동 금고 같은 등껍질에 작은 자물쇠 문양이 달린 거북이에요.','0.23','0.75','0.028',70,'rare','fish/rare/plunder-smuggler-vault-turtle_v1_thumbnail.png',235,'fish/rare/plunder-smuggler-vault-turtle_v1_sprite.png','plunder','swim',true,'both'),
('plunder-striped-piratefish','fish','줄무늬해적어','선원 같은 줄무늬와 붉은 등지느러미로 항로를 누비는 물고기예요.','0.2','0.75','0.028',49,'common','fish/normal/plunder-striped-piratefish_v1_thumbnail.png',62,'fish/normal/plunder-striped-piratefish_v1_sprite.png','plunder','swim',true,'both'),
('plunder-tattered-chart-ray','fish','찢어진 해도 가오리','날개 가장자리가 오래된 해도처럼 너덜너덜한 가오리예요.','0.28','0.76','0.028',78,'rare','fish/rare/plunder-tattered-chart-ray_v1_thumbnail.png',230,'fish/rare/plunder-tattered-chart-ray_v1_sprite.png','plunder','swim',true,'both'),
('plunder-treasure-chart-eel','fish','보물지도 비단뱀장어','양피지 같은 긴 몸에 붉은 항로와 보물 표시가 이어지는 뱀장어예요.','0.2','0.78','0.021',115,'epic','fish/epic/plunder-treasure-chart-eel_v1_thumbnail.png',800,'fish/epic/plunder-treasure-chart-eel_v1_sprite.png','plunder','swim',true,'both'),
('plunder-triangle-sail-jelly','fish','삼각돛 꼬마해파리','삼각 돛 같은 갓 아래로 짧은 돛줄 모양 촉수가 흔들려요.','0.18','0.64','0.028',52,'common','fish/normal/plunder-triangle-sail-jelly_v1_thumbnail.png',65,'fish/normal/plunder-triangle-sail-jelly_v1_sprite.png','plunder','pulse',true,'both'),
('plunder-twin-cannon-lobster','fish','쌍포갑옷 바닷가재','묵직한 황동 함포 같은 두 집게로 해저를 지키는 바닷가재예요.','0.85','0.95','0.012',98,'epic','fish/epic/plunder-twin-cannon-lobster_v1_thumbnail.png',725,'fish/epic/plunder-twin-cannon-lobster_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-twin-pistol-shrimp','fish','쌍권총 딱총새우','두 집게가 짧은 해적 권총처럼 생긴 날쌘 딱총새우예요.','0.85','0.95','0.012',62,'rare','fish/rare/plunder-twin-pistol-shrimp_v1_thumbnail.png',245,'fish/rare/plunder-twin-pistol-shrimp_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-wanted-bandit-crab','fish','수배범 도둑게','검은 눈가 무늬와 수배전단 같은 등껍질이 눈에 띄는 작은 게예요.','0.85','0.95','0.012',49,'common','fish/normal/plunder-wanted-bandit-crab_v1_thumbnail.png',54,'fish/normal/plunder-wanted-bandit-crab_v1_sprite.png','plunder','crawl',true,'both'),
('plunder-washed-bounty-poster','trash','상금이 지워진 수배전단','얼굴은 또렷하지만 현상금 숫자만 말끔하게 번졌어요.','0.89','0.96','0.001',48,'rare','trash/rare/plunder-washed-bounty-poster_v1_thumbnail.png',44,null,'plunder','fixed',false,'both'),
('plunder-wet-card-table','decoration','젖은 카드 테이블','카드 세 장과 술잔이 남은 작은 탁자예요. 다음 판을 기다리는 듯해요.',null,null,'0',58,'common','decorations/normal/plunder-wet-card-table_v1_thumbnail.png',38,null,'plunder','fixed',false,'both'),
('plunder-wreck-figurehead','decoration','난파선의 뱃머리 장식상','난파선에서 떨어져 나온 목조 장식상이에요. 바닷바람의 흔적이 남아 있어요.',null,null,'0',78,'rare','decorations/rare/plunder-wreck-figurehead_v1_thumbnail.png',184,null,'plunder','fixed',false,'both'),
('plunder-wreckback-turtle','fish','난파선등 거북','부서진 갑판과 기울어진 돛대를 등에 품은 오래된 바다거북이에요.','0.23','0.74','0.021',100,'epic','fish/epic/plunder-wreckback-turtle_v1_thumbnail.png',700,'fish/epic/plunder-wreckback-turtle_v1_sprite.png','plunder','swim',true,'both'),
('plunder-wrong-treasure-map','trash','틀린 곳을 가리키는 보물지도','보물 표시가 많지만 모두 지워져 있어요. 마지막 길도 막다른 길이에요.','0.89','0.96','0.001',48,'rare','trash/rare/plunder-wrong-treasure-map_v1_thumbnail.png',50,null,'plunder','fixed',false,'both')
